import { zodResolver } from '@hookform/resolvers/zod';
import { useRef } from 'react';
import { Controller, useForm } from 'react-hook-form';
import { Alert, KeyboardAvoidingView, Platform, Text, TextInput, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { Card, Field, PrimaryButton } from '@/components/ui';
import { setPasswordSchema, type SetPasswordValues } from '@/lib/schemas';
import { useShift } from '@/lib/shift';

/**
 * Shown once, to a guard whose account was opened for them by an admin.
 *
 * That password was generated by the dashboard, shown on screen and handed
 * over — usually read aloud at a gate. By the time it is first used, at least
 * two people know it, and the person it does NOT belong to is the one who
 * chose it. This is where it stops being the handover password.
 *
 * onboard-guard has always set profiles.must_change_password for these
 * accounts. Nothing in this app read it, so the flag described the account
 * accurately and changed nothing for the guard holding it. This screen is the
 * other half.
 *
 * It sits BEFORE the keypad rather than in a settings screen. A guard opens
 * this app to work a gate and closes it when the shift ends; a prompt they can
 * postpone is a prompt that is postponed until the account is deactivated.
 * They can still sign out, which is the honest escape hatch — but they cannot
 * reach the keypad carrying a password somebody else picked.
 */
export default function SetPassword() {
  const { session, setPassword, endShift } = useShift();
  const confirmRef = useRef<TextInput>(null);

  const {
    control,
    handleSubmit,
    setError,
    formState: { errors, isValid, isSubmitting },
  } = useForm<SetPasswordValues>({
    resolver: zodResolver(setPasswordSchema),
    // onTouched, matching start-shift: the "do not match" error is true for
    // most of the time it takes to type the second field, and showing it at
    // every keystroke teaches a guard to ignore the message.
    mode: 'onTouched',
    defaultValues: { password: '', confirm: '' },
  });

  const submit = handleSubmit(async ({ password }) => {
    const { error } = await setPassword(password);
    if (error) {
      // On the field, not only in an alert, so the reason survives the guard
      // dismissing it. Supabase rejects a password it considers too weak or
      // previously used, and that message is about this field.
      setError('password', { message: error });
      Alert.alert('Could not set that password', error);
    }
    // On success the Gate routes to the keypad — mustChangePassword is false.
  });

  return (
    <SafeAreaView className="flex-1 bg-canvas" edges={['top', 'bottom']}>
      <KeyboardAvoidingView
        behavior={Platform.OS === 'ios' ? 'padding' : undefined}
        className="flex-1 px-5 pb-6"
      >
        <View className="flex-1 justify-center">
          <Text className="max-w-measure font-jk-xb text-display tracking-tight text-ink">
            Choose your own password
          </Text>
          <Text className="mt-2 max-w-measure font-jk text-body text-muted">
            Your account was opened with a password somebody read out to you. Anyone who saw it can
            sign in as you until you replace it.
          </Text>

          <View className="mt-7 gap-1">
            <Controller
              control={control}
              name="password"
              render={({ field: { onChange, onBlur, value } }) => (
                <Field
                  autoFocus
                  label="New password"
                  placeholder="New password"
                  secureTextEntry
                  autoCapitalize="none"
                  autoComplete="new-password"
                  returnKeyType="next"
                  // "submit" keeps the keyboard up for the focus handoff;
                  // blurOnSubmit was replaced by submitBehavior in RN 0.79.
                  submitBehavior="submit"
                  onSubmitEditing={() => confirmRef.current?.focus()}
                  value={value}
                  onChangeText={onChange}
                  onBlur={onBlur}
                  error={errors.password?.message}
                />
              )}
            />
            <Controller
              control={control}
              name="confirm"
              render={({ field: { onChange, onBlur, value } }) => (
                <Field
                  ref={confirmRef}
                  label="Repeat it"
                  placeholder="Repeat it"
                  secureTextEntry
                  autoCapitalize="none"
                  autoComplete="new-password"
                  returnKeyType="go"
                  onSubmitEditing={() => void submit()}
                  value={value}
                  onChangeText={onChange}
                  onBlur={onBlur}
                  error={errors.confirm?.message}
                />
              )}
            />
          </View>

          <PrimaryButton
            title={isSubmitting ? 'Saving…' : 'Save and start'}
            onPress={() => void submit()}
            disabled={!isValid || isSubmitting}
            className="mt-4"
          />

          <Card className="mt-6 p-4">
            <Text className="font-jk text-sub text-muted">
              Signed in as {session?.user.email ?? 'this account'}. Not you?{' '}
              <Text className="font-jk-b text-ink" onPress={() => void endShift()}>
                Sign out
              </Text>
              .
            </Text>
          </Card>
        </View>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}
